mapper.select:
SELECT 
FROM tbl_connected_account
WHERE id = #{id}
  AND user_id = #{userId}

mapper.update:
UPDATE tbl_connected_account
SET is_active = 0
WHERE id = #{id}
  AND user_id = #{userId}

UPDATE tbl_connected_account
SET is_active = 0
WHERE user_id = #{userId}
  AND account_no_encrypted = #{accountNoEncrypted}

UPDATE tbl_connected_account
SET sync_status      = #{syncStatus},
    last_sync_at     = #{lastSyncAt},
    sync_fail_reason = #{syncFailReason}
WHERE id = #{id}
  AND user_id = #{userId}

UPDATE tbl_connected_account
SET sync_status      = 'NORMAL',
    sync_fail_reason = NULL,
    balance          = #{balance},
    last_sync_at     = #{lastSyncAt}
WHERE id = #{id}
  AND user_id = #{userId}

mapper.select:
SELECT ca.user_id FROM tbl_connected_account ca JOIN tbl_user u ON u.id = ca.user_id LEFT JOIN ( SELECT user_id, MAX(finished_at) AS last_attempt_at FROM tbl_financial_sync_history GROUP BY user_id ) h ON h.user_id = ca.user_id WHERE ca.is_active = 1 GROUP BY ca.user_id, h.last_attempt_at, u.financial_data_source HAVING h.last_attempt_at IS NULL OR h.last_attempt_at < DATE_SUB(NOW(), INTERVAL
#{codefThresholdMinutes}
CASE WHEN u.financial_data_source = 'CODEF' THEN #{codefThresholdMinutes} ELSE #{thresholdMinutes} END
#{thresholdMinutes}
MINUTE) ORDER BY h.last_attempt_at ASC LIMIT #{limit}

mapper.delete:
DELETE FROM tbl_connected_account
WHERE user_id = #{userId}
  AND account_no_encrypted = #{accountNoEncrypted}
  AND is_active = 0
